from tools.experiments.area_projection_peer.test_projection_controller import package,make,cmd,ev,capture,INPUTS,CAPTURES,deepcopy,pytest
def test_nested_area_after_first_child_camo_uses_new_actual_projection():
 p=package();outer=p['abilities'][0]['timeline'][0]['effect'];inner=deepcopy(outer);outer['effects']=[{'op':'apply_buff','buff':'buff/peer/camo'},inner];s=make(p);cmd(s,'area',0);s.advance(4);capture(s,'nested_fresh_flags');areas=ev(s,'area.resolved');assert len(areas)==2 and list(areas[0]['payload']['members'])==[3] and list(areas[1]['payload']['members'])==[] and s.ctx.resources.current('corner','hp')==101
def test_source_sees_camo_current_buff_before_impact_not_static_default():
 p=package();p['abilities'].append({'id':'ability/peer/see','kind':'ability','activation':{'mode':'manual','on_start':[{'op':'apply_buff','target':2,'buff':'buff/peer/see'}]},'timeline':[]});p['entities'][-1]['components']['abilities'].append('ability/peer/see');s=make(p);cmd(s,'area',0);cmd(s,'camo',2);s.submit({'action':'skill','source':'director','ability':'ability/peer/see'},at=1);s.advance(4);capture(s,'source_cansee');assert s.ctx.resources.current('corner','hp')==90
def test_invalid_second_child_rolls_back_first_projection_hit_and_all_area_events():
 p=package();p['rules'].append({'id':'rule/peer/fault','kind':'rule','contract':'damage.pipeline','implementation':{'type':'graph','nodes':[{'id':'bad','expression':'1/0'}],'output':'nodes.bad'}});p['entities'][0]['components']['attributes']={'base':{'max_hp':101,'atk':13,'def':31,'mres':17}};p['entities'][1]['components']['attributes']['base'].update(atk=0,**{'def':31,'mres':17});p['abilities'][0]['timeline'][0]['effect']['effects'].append({'op':'damage','damage_type':'true','rules':{'damage.pipeline':'rule/peer/fault'}});s=make(p);cmd(s,'area',0);s.advance(3)
 with pytest.raises(Exception):s.advance(1)
 capture(s,'late_area_fault');assert not ev(s,'area.resolved') and s.ctx.resources.current('corner','hp')==101
